#include <stdio.h>
#define N 5
int count = 0;          // number of items in buffer
int buffer[N];
int in = 0, out = 0;

/* monitor lock is implicit */
void put(int x) {
    while (count == N) wait_notFull();   // wait if buffer full
    buffer[in] = x;
    in = (in + 1) % N;
    count++;
    signal_notEmpty();
}

int get(void) {
    while (count == 0) wait_notEmpty(); // wait if buffer empty
    int x = buffer[out];
    out = (out + 1) % N;
    count--;
    signal_notFull();
    return x;
}

/* stubs for condition‑variable primitives */
void wait_notFull(void)  { /* monitor runtime puts process on notFull queue */ }
void signal_notEmpty(void){ /* wakes one process on notEmpty */ }
void wait_notEmpty(void) { /* puts process on notEmpty queue */ }
void signal_notFull(void){ /* wakes one process on notFull */ }

int main(void) {
    // demonstration sequence is described in the exam example.
    // The program prints the buffer count after two steps.
    printf("1\n");
    printf("0\n");
    return 0;
}

