#include <stdio.h>
int main(void) {
    int N = 5, count = 0;
    int prod_wait = 0, cons_wait = 0;
    // step 1: put 5 items
    count = 5;
    // step 2: try to put 6th item
    if (count == N) prod_wait++;
    // step 3: consumer gets two items
    count -= 2;
    // step 4: producer puts item 6 after being woken
    count += 1;
    // step 5: consumer gets remaining four items
    count -= 4;
    printf("%d\n%d\n", prod_wait, cons_wait);
    return 0;
}
